// History population records; exact public sources were opened on 2026-09-07.
const records = [];
const source = (id, lineage, type, citation, url, locator) => ({sourceId:`history-${id}`,lineageId:lineage,sourceType:type,citation,url,locator,accessedDate:'2026-09-07',accessStatus:'anonymous_full_content',reuseStatus:'publicly_accessible_citation_only',permissionBasis:'Publicly readable source, independently paraphrased. No permission to reproduce its prose or figures is asserted.',supports:['history']});
const patent = (id,citation,locator) => source(id.toLowerCase(),`patent-${id.toLowerCase()}`,'patent',citation,`https://patents.google.com/patent/${id}/en`,locator);
const add = (n,history,...sources) => records.push({wopId:`wop-${String(n).padStart(6,'0')}`,history,sources});
const fluorine = source('organofluorine-history','organofluorine-industry-history','open_journal','T. Okazoe, Overview on the history of organofluorine chemistry from the viewpoint of material industry, Proceedings of the Japan Academy, Series B 85 (2009), 276–289.','https://pmc.ncbi.nlm.nih.gov/articles/PMC3621566/','Fluoropolymers and Functionalized fluoropolymers sections; PFA, PCTFE, ETFE and TFE–propylene chronology.');
const chemours = source('chemours-timeline','chemours-corporate-history','manufacturer_technical_document','Chemours, Our History.','https://www.chemours.com/en/about-chemours/history','Fluoroproducts timeline, 1970 Tefzel wire and cable insulation milestone.');
const daikin = source('daikin-chronology','daikin-corporate-history','manufacturer_technical_document','Daikin Industries, Chronology.','https://www.daikin.com/corporate/overview/summary/history/chronology','1953 DAIFLON PCTFE development, 1955 PTFE and 1970 DAIEL fluoroelastomer milestones.');
add(91,'PFA emerged from efforts to obtain melt-processable fluoropolymers while retaining a fully fluorinated backbone. DuPont commercialized it in 1972. A contemporary patent by William Franklin Gresham and Alfons Franz Vogelpohl, issued that year, describes aqueous copolymerization of tetrafluoroethylene with perfluoroalkyl vinyl ethers and addresses polymer quality. This was a process-development milestone, rather than evidence that every present PFA composition was invented simultaneously. PFA belongs to the subsequent diversification of fluoroplastics into materials that could be shaped by conventional melt conversion; control of the vinyl-ether component and polymerization conditions was central to that development.',fluorine,patent('US3635926A','W. F. Gresham and A. F. Vogelpohl, Aqueous process for making improved tetrafluoroethylene/fluoroalkyl perfluorovinyl ether copolymers, US 3635926 A (1972).','Description, prior processing difficulties and aqueous copolymerization process; front-page inventor and date information.'));
add(92,'ETFE entered commercial fluoroplastics during the early 1970s. Chemours dates the introduction of DuPont’s Tefzel plastics to 1970 and associates the development with wire and cable insulation. An industry-history review instead dates independent DuPont and Asahi Glass commercialization to 1972; these sources therefore support an early-1970s transition more securely than one universal launch date. Cable insulation was a principal early market. Tough, flexible ETFE films subsequently established an architectural use alongside electrical applications. The material’s history reflects industrial copolymer development and conversion into films and insulated conductors, rather than the original discovery of PTFE.',chemours,fluorine);
add(93,'ECTFE’s established industrial history centers on chemically resistant barriers and electrical protection. Zeus’s public material account documents Halar resin and its own extrusion of tubing and drawn fiber for chemical transfer, automotive wiring and aerospace wire harnesses. These sources do not settle an original invention date. A distinct recent advance was reported online in December 2025 by Mengli Xu, Qiankai Chen, Mao Chen and colleagues: photoredox-controlled copolymerization gave alternating ECTFE with chain ends that could be extended into blocks. That laboratory development broadened control of molecular architecture; it should be distinguished from the older commercial resin and its long-established protective uses.',source('zeus-ectfe-history','zeus-ectfe-material-introduction','manufacturer_technical_document','Zeus Industrial Products, ECTFE—Ethylene Chlorotrifluoroethylene: Material Introduction.','https://www.zeusinc.com/wp-content/uploads/2023/02/ECTFE-Material-V2R1.pdf','Page 1, overview and applications.'),source('xu-ectfe-2026','chen-ectfe-photoredox-research','open_journal','M. Xu, Q. Chen, S. Han, K. Chen, X. Guo and M. Chen, Photoredox-controlled alternating copolymerization enables highly crystalline structures and block copolymers from thermoplastic to elastomer, Nature Communications 17 (2026), 265; published online 12 December 2025.','https://www.nature.com/articles/s41467-025-66962-8','Introduction and Results: established ECTFE uses, conventional polymerization and photoredox chain extension.'));
add(94,'PCTFE entered postwar commerce through M. W. Kellogg’s Kel-F, becoming generally available in the early 1950s; 3M took over that business in 1957. Daikin independently records development of its DAIFLON PCTFE in 1953. These production milestones do not settle the earliest synthesis of the polymer. Later industrial uses included cryogenic valve seats and seals, chemical-processing components and aerospace hardware. The original Kel-F business ended in the 1990s, while resin supply continued through other manufacturers. Drake’s account documents its own later conversion of Arkema Voltalef resin into machinable shapes and precision components, showing how specialized fabrication extended the material’s engineering applications.',fluorine,daikin,source('drake-pctfe-history','drake-pctfe-product-overview','manufacturer_technical_document','Drake Plastics, Drake PCTFE: Comprehensive Overview.','https://drakeplastics.com/drake-pctfe-comprehensive-overview/','Kel-F business lineage, resin sources, Drake conversion of Voltalef resin and cryogenic/chemical/aerospace application sections.'));
add(95,'Arkema traces its Kynar PVDF business to Pennsalt’s development of the resin in 1960 and completion of a Calvert City production plant in 1965. Kynar 500 architectural-coating resin was introduced in 1965; this grade’s launch should not be mistaken for the first synthesis of PVDF itself. The coating grade became a durable finish for exterior metalwork, sold through licensed paint companies and used on prominent buildings. Later Arkema expansion addressed water management and new-energy applications, continuing the business inherited through Pennsalt and Pennwalt.',source('arkema-us-pvdf-history','arkema-us-corporate-history','manufacturer_technical_document','Arkema, History of Arkema in the United States.','https://www.arkema.com/usa/en/united-states/arkema-united-states/arkema-inc-history/','1960 and 1965 Kynar entries; 2015 anniversary and 2017 expansion entries.'),source('arkema-kynar-50','arkema-kynar-anniversary','manufacturer_technical_document','Arkema, Arkema celebrates 60th anniversary of its flagship Kynar 500, 2025.','https://www.arkema.com/usa/en/media/news/global/corporate/2025/20250323-Kynar-500-60-year-anniversary/','Sixty-year architectural coating history, licensed paint production and metal-building applications.'));
add(96,'The commercial history of the TFE–HFP–VDF terpolymer is closely associated with THV and the collaboration between Hoechst and 3M. In its company history, 3M describes the formation of the Dyneon joint venture in 1996 and development of THV applications using Hoechst’s manufacturing capability and 3M’s market experience. Documented uses included automotive fuel-filler tube linings, greenhouse films and fiber-optic tubing. 3M bought Hoechst’s interest at the end of 1999. These are commercialization and application-development milestones; the account does not establish that the terpolymer was first synthesized when the joint venture was formed.',source('3m-thv-history','3m-century-of-innovation','manufacturer_technical_document','3M, A Century of Innovation (2002).','https://multimedia.3m.com/mws/media/171240O/3m-century-of-innovation-book.pdf','Chapter 11, printed page 182, Dyneon alliance and THV applications.'));
add(97,'Michael Szwarc discovered vapor-deposited poly(p-xylylene) during high-temperature studies of para-xylene at Manchester in 1947. His deposit prompted industrial investigation by ICI, DuPont, Kellogg and Polaroid. William Franklin Gorham at Union Carbide subsequently developed a more practical deposition route using the cyclic dimer; Donald Cram’s laboratory contributed a dimer synthesis in 1951. Union Carbide announced the commercial Parylene coating system on 17 February 1965. The principal historical product was therefore a deposited protective coating, with polymer chemistry and application method developed together. Nova Tran licensed the technology in 1971; the later Specialty Coating Systems business continued its commercialization.',source('scs-parylene-history','scs-parylene-history','manufacturer_technical_document','Specialty Coating Systems, History of Parylene.','https://scscoatings.com/parylene-coatings/parylene-history/','Szwarc discovery, Gorham process, 1965 announcement and commercialization chronology.'));
const castan = patent('US2324483A','P. Castan, Process of preparing synthetic resins, US 2324483 A (1943), Swiss priority 1938.','Description and examples 2–3; proposed molding, electrical and varnish uses; front-page dates.');
const araldite = source('araldite-legacy','araldite-brand-history','manufacturer_technical_document','Araldite, The Araldite Legacy.','https://www.go-araldite.com/en/araldite-legacy','1946 epoxy-technology launch and development of adhesive applications.');
add(98,'Modern epoxy-resin development involved several inventors and commercial routes. Pierre Castan’s patent, claiming Swiss priority in 1938 and issued in the United States in 1943, describes curing polyphenol–epichlorohydrin products with acid anhydrides. It proposed cast and molded articles, electrical components and varnishes. Independently, Sylvan Owen Greenlee at Devoe & Raynolds developed epoxy-derived drying compositions for coatings, documented in his 1948 patent. The Araldite brand dates its epoxy technology to 1946 and subsequently served industrial and household bonding. These early molding, coating and adhesive routes explain why the epoxy family developed as a platform of resins and curing systems rather than one fixed polymer.',castan,patent('US2456408A','S. O. Greenlee, Synthetic drying compositions, US 2456408 A (1948).','Description, Devoe & Raynolds assignment and coating compositions.'),araldite);
add(99,'Bisphenol A–epichlorohydrin chemistry was present in Castan’s foundational epoxy patent, with Swiss priority in 1938 and United States publication in 1943. Its examples prepare the resin and cure it with phthalic or adipic anhydride, while the proposed uses include molded electrical articles and varnish. This chemistry became a central branch of the commercial epoxy industry. Araldite’s history dates its epoxy-technology launch to 1946 and records subsequent industrial and domestic adhesive markets. The invention and commercialization milestones concern resin systems and hardeners; they do not imply that all present liquid, solid or formulated DGEBA grades originated in the same year.',castan,araldite);
add(100,'Bisphenol F epoxy developed as a distinct branch of glycidyl-ether resin technology. By 1968, John Pfann and Adam Kopacki’s Stauffer Chemical patent already listed bisphenol F glycidyl ethers among commercial epoxy resins, so that date is a documented lower bound on established use rather than an invention claim. Later formulation work sought advantages in demanding coatings: a 1993 flooring patent identifies Shell’s EPON DPL-862 bisphenol F resin and develops hardener and aggregate combinations for impact and chemical resistance. This history illustrates how supplier resin development and application-specific formulation advanced the material after its initial introduction.',patent('US3395121A','J. R. Pfann and A. F. Kopacki, Curing epoxy resins with boron trichloride–tertiary amine complexes, US 3395121 A (1968), Stauffer Chemical.','Description, list of already-commercial epoxy resins.'),patent('US5225455A','Bisphenol epoxy-based flooring and coating materials, US 5225455 A (1993).','Background and preferred embodiments identifying Shell EPON DPL-862 and industrial flooring needs.'));
add(101,'Epoxy novolacs combined established phenolic-resin chemistry with the expanding epoxy industry. Theodore Bradley and Herbert Newey at Shell Development filed a patent in 1952, issued in 1955, on epoxy resins made from alkylphenol novolacs. It documents an early route to resins with multiple reactive sites, rather than proving the first invention of every epoxy-novolac subtype. By 1968 Stauffer Chemical’s curing-agent patent listed epoxidized novolacs among commercial epoxy materials. Their history therefore includes both precursor synthesis and curing-system development, with coating and thermoset formulation work exploiting the additional functionality.',patent('US2716099A','T. F. Bradley and H. A. Newey, Epoxy resins from alkyl phenol novolac resins, US 2716099 A (1955), Shell Development.','Description of epichlorohydrin reaction, coating and cured-resin uses; filing date 1952.'),patent('US3395121A','J. R. Pfann and A. F. Kopacki, Curing epoxy resins with boron trichloride–tertiary amine complexes, US 3395121 A (1968).','Description listing epoxidized novolacs as commercial resins.'));
add(102,'Glycidyl amine epoxies illustrate the conversion of known small-molecule chemistry into engineering resins. Norman Reinking’s Union Carbide patent, filed in 1956 and issued in 1960, explicitly states that aromatic glycidyl amines had previously been prepared for biological investigation, but that their resin potential had not been appreciated. His work improved synthesis of products with high epoxy content and described formulations combining workable uncured resins with high heat-distortion resistance after cure. Thus 1960 is an identifiable resin-development milestone, not the first preparation of all glycidyl amines. The historical advance was the practical use of multifunctional aromatic amines as epoxy precursors.',patent('US2951822A','N. H. Reinking, Preparation of polyglycidyl aromatic amines and resinous compositions made therefrom, US 2951822 A (1960), Union Carbide.','Opening description, earlier glycidyl-amine work, two-stage synthesis and resin objectives.'));
add(103,'Cycloaliphatic epoxies developed along a route distinct from bisphenol glycidyl ethers. Union Carbide’s 1972 patent traces relevant diepoxide monomers to Benjamin Phillips and colleagues’ patents of 1956 and 1959. The 1972 work addressed a practical limitation of liquid cycloaliphatic epoxides by making solid, curable intermediates. It targeted molding, coatings and laminates, emphasizing electrical applications after cure. These documents establish a sequence from postwar monomer chemistry to handling and formulation improvements. They support a history of several related monomers and resin systems, rather than one invention date for the entire cycloaliphatic epoxy category.',patent('US3704268A','Curable, solid polymers based on cycloaliphatic polyepoxides and a method for the preparation thereof, US 3704268 A (1972), Union Carbide.','Opening description, intended molding/coating/laminating uses and references to Phillips patents of 1956 and 1959.'));
const upr = source('bpf-unsaturated-polyester','bpf-unsaturated-polyester-history','institutional_reference','British Plastics Federation, Unsaturated Polyester UP.','https://www.bpf.co.uk/plastipedia/polymers/Unsaturated_Polyester.aspx','Historical section, Carleton Ellis, reactive monomers, aircraft ducting, boat hulls and conversion methods.');
add(104,'Carleton Ellis developed the modern unsaturated-polyester concept in the 1930s: unsaturated polyester could be cured with a peroxide, and reactive monomers such as styrene made the system easier to use. His patent work dates from 1936. Early glass-reinforced applications included aircraft ducting, followed by civilian boat hulls. Pultrusion and filament winding widened use to rods, electrical insulation, pipes and storage vessels. The important historical transition was from polyester chemistry to resin systems that could wet reinforcement and cure into shaped composites; later orthophthalic, isophthalic and modified grades represent diversification within that platform.',upr);
add(105,'Orthophthalic unsaturated polyester belongs to the resin technology developed around Carleton Ellis’s 1930s work on unsaturated polyesters and reactive monomers. His 1941 patent includes phthalic-anhydride-containing formulations, documenting that this chemistry was already part of the early development period. The subsequent glass-reinforced polyester industry grew through aircraft ducting, boat hulls and other molded products. The parent-family history is better documented than a separate first-invention date for the orthophthalic grade category. Its historical significance lies in adapting an accessible aromatic acid component to practical reactive composite-resin formulations.',patent('US2255313A','C. Ellis, Ethylenic-alpha-beta synthetic resins and process of making same, US 2255313 A (1941).','Description and examples including phthalic anhydride; relation to applications filed in 1936–1937.'),upr);
add(106,'Isophthalic unsaturated polyester was an established development target by the 1950s. E. F. Carlston and G. B. Johnson’s California Research patent, filed in 1954 and issued in 1959, addressed the order of reaction: first forming an isophthalic-acid/glycol intermediate, then incorporating the unsaturated acid. The aim was to obtain useful curable polyester compositions without the difficulties encountered when all components were combined together. This provides a concrete process milestone in the diversification of unsaturated polyester resins. It does not establish a unique first-invention date for every isophthalic formulation or convert the patent examples into universal properties.',patent('US2904533A','E. F. Carlston and G. B. Johnson, Preparation of unsaturated polyesters by the reaction of, first, isophthalic acid and a glycol, followed by reaction with unsaturated aliphatic polybasic acid, US 2904533 A (1959).','Description and examples, staged preparation and curable resin compositions; 1954 filing.'));
add(107,'Dicyclopentadiene modification was part of the later diversification of unsaturated polyester resins. A clear milestone is Omer Curtis’s United States Steel patent, filed in 1979 and issued in 1980, which develops DCPD-containing polyester formulations and demonstrates glass-reinforced laminates. It treats formulation, dilution with reactive vinyl monomers and curing as linked design problems. The examples include resins usable in laminating and molding, showing the application-driven character of the development. This patent documents an established route and its improvement; it should not be read as the first discovery of all DCPD-modified polyesters.',patent('US4233432A','O. E. Curtis Jr., Dicyclopentadiene polyester resins, US 4233432 A (1980), United States Steel.','Description of earlier DCPD work, resin preparation, reinforcement and laminate examples.'));
const derakane = source('derakane-anniversary','ashland-derakane-history','manufacturer_technical_document','Ashland, Derakane epoxy vinyl ester resins: fiftieth anniversary announcement, 5 March 2015.','https://investor.ashland.com/news-releases/news-release-details/ashlands-derakanetm-epoxy-vinyl-ester-resins-continue-delivering','1965 invention, initial chlorine/pulp-bleaching and wastewater markets, subsequent corrosion-resistant composites.');
add(108,'A major commercial milestone for epoxy vinyl esters was the 1965 development of Derakane for hot, wet, corrosive chlorine service. Ashland’s fiftieth-anniversary history identifies pulp bleaching and wastewater treatment as the original target markets, followed by chemical processing, air-pollution control and mineral processing. The family combined epoxy-derived precursors with a radical-curable resin system suited to reinforced plastics. Subsequent development also addressed formulation emissions: Giuseppe Palmese, John La Scala and James Sands’s 2008 patent describes multimodal vinyl esters intended to reduce volatile diluent requirements. The Derakane date applies to that product lineage, not necessarily the first synthesis of every vinyl ester.',derakane,patent('US20080039590A1','G. Palmese, J. La Scala and J. Sands, Multi-Modal Vinyl Ester Resins, US 2008/0039590 A1 (2008).','Background and summary of low-VOC multimodal resin development.'));
add(109,'Bisphenol A epoxy vinyl ester is one branch of the corrosion-resistant vinyl-ester industry whose Derakane lineage began in 1965. That product family first addressed chlorine-containing pulp-bleaching and wastewater environments. The family launch is not a separate invention date for all bisphenol A grades. A later research milestone is Palmese, La Scala and Sands’s 2008 patent, which uses bisphenol A epoxy-derived vinyl esters in multimodal formulations to reduce dependence on volatile reactive diluents. This records a shift from establishing reinforced corrosion-resistant plastics toward improving the formulation and processing of an established resin chemistry.',derakane,patent('US20080039590A1','G. Palmese, J. La Scala and J. Sands, Multi-Modal Vinyl Ester Resins, US 2008/0039590 A1 (2008).','Background and bisphenol A epoxy-based resin examples.'));
add(110,'Epoxy-novolac vinyl esters developed within the vinyl-ester industry as a separate, more highly functional resin branch. By 1997, F. V. Apicella Jr. and N. A. Dulzer’s patent explicitly used Dow’s commercial Derakane 470.36 novolac vinyl ester as a comparison material. Their work on curable compositions and protective applications demonstrates that this subtype had an established industrial identity by then. The comparison also shows why resin structure, cure package and application conditions must be tracked together. The source establishes a dated commercial-use milestone, but does not identify the first synthesis or launch of every epoxy-novolac vinyl ester.',patent('GB2308375A','F. V. Apicella Jr. and N. A. Dulzer, Curable compositions, GB 2308375 A (1997).','Description and Table 2, Dow Derakane 470.36 novolac vinyl ester comparison and curable protective compositions.'));
const bakelite = source('acs-bakelite','acs-bakelite-landmark','institutional_reference','American Chemical Society, Leo Hendrik Baekeland and the Invention of Bakelite, National Historic Chemical Landmark.','https://www.acs.org/education/whatischemistry/landmarks/bakelite.html','Baekeland and Thurlow investigations, 1907 development, 1909 announcement, 1910 production and historical uses.');
add(111,'Phenol–formaldehyde reactions were known before Leo Baekeland made them commercially useful. Baekeland and Nathaniel Thurlow initially sought a shellac substitute, then developed controlled heat-and-pressure curing in 1907. Baekeland publicly announced Bakelite in 1909 and formed a manufacturing company in 1910. Electrical insulators were an early market; radio components, automobile distributor caps, telephones, handles and household objects followed. The decisive contribution was control of an otherwise difficult condensation reaction and its conversion into reproducible molded products. Bakelite established the commercial thermoset industry, although the broader phenolic family subsequently encompassed many formulations and application-specific resins.',bakelite);
add(112,'Novolac history reaches back to Baekeland and Thurlow’s search for a synthetic shellac before the successful Bakelite thermoset. Their initial Novolak product was commercially unsuccessful, but fusible phenolic precursors became an enduring branch of resin technology. A later milestone is Myron Annis’s 1980 patent on improving low-temperature processing stability of novolac-based phenolic compositions. Its focus on workable resin mixtures and subsequent cure illustrates the transition from an early coating substitute to engineered molding materials. The history of novolacs is therefore connected to, but not identical with, the 1907 invention of the fully cured Bakelite product.',bakelite,patent('US4239869A','M. C. Annis, Phenolic resins with improved low temperature processing stability, US 4239869 A (1980).','Description, novolac compositions and processing-stability objective.'));
add(113,'Resoles belong to the phenolic-resin technology established by Baekeland’s controlled condensation and curing work in 1907–1909. The term identifies a reactive precursor class rather than a separately documented single invention. Later manufacturers refined how such resins were prepared and stored. A 1987 patent on phenol–formaldehyde resole production provides a specific example of continuing process development: controlling the alkaline condensation to obtain useful resin products. This trajectory links the early heat-cured phenolic industry with later application-specific binders and resin formulations, while leaving the exact first use of the modern resole designation unresolved.',bakelite,patent('US4656239A','Process for the preparation of phenol formaldehyde resole resins, US 4656239 A (1987).','Field, background and process description.'));
add(114,'Cresol–formaldehyde resins developed within the broader phenolic industry, but their history cannot be reduced to the date of Bakelite’s invention. A concrete mid-century development is the work of Gene Weber, Robert Hoyt and Robert Dinsmore at Richfield Oil: their 1954 application, patented in 1958, describes cresol-derived coatings made from petroleum cresylic acids. They sought formulations that could be stored, brushed or sprayed and cured under ordinary atmospheric conditions. Asphalt roofing protection was an explicit use. This records how a phenolic resin variant was adapted to protective coatings and petroleum-derived feedstocks, rather than establishing its first synthesis.',patent('US2834745A','G. C. Weber, R. P. Hoyt and R. L. Dinsmore, Method of producing cresol-formaldehyde polymer coating compositions, US 2834745 A (1958), Richfield Oil.','Opening description, storage and ambient-curing objectives, asphalt roofing applications.'));
add(115,'Resorcinol–formaldehyde resins acquired historical importance as durable adhesives. Harry Bradley at Firestone filed a 1946 patent, issued in 1950, that developed stable resorcinol-containing cements for bonding to metals and other surfaces. A specific target was adhesion of fuel-sealing coatings inside aircraft fuel compartments, where fuel, water and low-temperature exposure challenged existing systems. The patent treats resorcinol–formaldehyde resin as already known and therefore documents an application advance rather than the first synthesis. Its emphasis on storage life, workable cements and reliable interfaces captures a central theme in the material’s development: turning rapid condensation chemistry into practical bonding systems.',patent('US2514196A','H. P. Bradley, Resorcinol formaldehyde adhesive, US 2514196 A (1950), Firestone Tire & Rubber.','Opening description and aircraft fuel-compartment adhesive objectives; 1946 filing.'));
add(116,'Phenol–resorcinol–formaldehyde adhesives developed as a compromise between the room-temperature curing and durability of resorcinol adhesives and the lower cost of phenol. Myron Dietrich’s Koppers patent, filed in 1964 and issued in 1967, describes that rationale explicitly and presents sulfite-catalyzed resins with improved storage and dilution behavior. The patent treats modified phenolic adhesives as an existing commercial technology, so it is a development milestone rather than an invention date for the whole family. Historically, progress depended as much on usable shelf life, hardener addition and glue consistency as on producing the cured network.',patent('US3328354A','M. I. Dietrich, Phenol-resorcinol-formaldehyde resins and the process of making them, using an alkali metal sulfite catalyst, US 3328354 A (1967), Koppers.','Opening background, cost/performance rationale and storage-stability problem.'));
add(117,'Urea–formaldehyde developed commercially through several interwar investigations rather than one isolated invention. The Plastics Historical Society records F. Pollak’s Vienna group and its 1920–1924 patents, followed by industrial work on practical molding materials. Compared with early filled phenolics, these resins allowed pale, translucent and brightly colored articles. Early outlets included electrical fittings, telephone and radio housings, lampshades, decorative boxes and tableware. Melamine subsequently displaced UF in many tableware applications. The history illustrates both the importance of controlling condensation and the role of color and appearance in extending synthetic plastics into consumer products.',source('phs-urea-history','plastics-historical-society-uf','institutional_reference','The Plastics Historical Society, Urea formaldehyde.','https://plastiquarian.com/?page_id=14236','Full historical account, Pollak patents and early molding applications.'));
add(118,'Melamine–formaldehyde resin became industrially practical during the 1930s, when melamine manufacture and resin condensation were developed together. Yuan Wang’s Waikato history identifies Henkel’s resin production and patenting around 1935 and Ciba’s contemporaneous commercially feasible melamine route. The resin’s combination of hard surfaces and resistance to water and heat helped establish molding, decorative laminates and protective-surface applications. Wang’s 2012 investigation, undertaken for Momentive Specialty Chemicals, represents a later stage: quantitative NMR was used to follow resin formation up to an industrial production endpoint. Thus the history runs from feedstock availability to consumer and industrial surfaces and continuing control of resin manufacture.',source('wang-mf-history','waikato-wang-melamine-research','thesis','Y. Wang, University of Waikato thesis on real-time NMR analysis of melamine–formaldehyde resin formation (2012).','https://researchcommons.waikato.ac.nz/bitstreams/e394f971-12be-4c2e-b4aa-953e770ca517/download','Abstract and introductory resin history, printed pages 1–4; Henkel and Ciba milestones.'));
add(119,'Melamine–urea–formaldehyde belongs to the development of mixed amino-resin adhesives from the established UF and MF chemistries. Its history is application-driven: adding melamine sought improved resistance to moisture while retaining the economic advantages of urea-rich formulations. By 2013, Jun Zhang, Xiaodong Wang, Shifeng Zhang, Qiang Gao and Jianzhang Li were investigating how the stage of melamine addition altered resin performance and curing. This is a documented research milestone in wood-adhesive development, not evidence for a first invention in 2013. The resulting family encompasses different addition sequences and compositions, so no single launch date can represent all MUF adhesives.',source('zhang-muf-2013','zhang-muf-addition-stage','open_journal','J. Zhang, X. Wang, S. Zhang, Q. Gao and J. Li, Effects of Melamine Addition Stage on the Performance and Curing Behavior of Melamine–Urea–Formaldehyde Resin, BioResources 8 (2013), 5500–5514.','https://bioresources.cnr.ncsu.edu/BioRes_08/BioRes_08_4_5500_Zhang_WQZL_Melamine_Stage_Performance_Curing_Resin_4143.pdf','Introduction, experimental resin series and conclusions on melamine addition stage in wood adhesives.'));
add(120,'Phenol–urea–formaldehyde combinations were already the subject of Pierre Cuvier’s patent issued in 1943, with a 1940 priority date. This is an early documented synthesis milestone, rather than a universal invention date for mixed phenolic/amino resins. Subsequent industrial work refined the balance between phenolic modification and UF processing. Frederick Schwartzenburg Jr. and Donald Griffin at Reichhold patented a controlled phenol-modified UF process in 1970, evaluating adhesive working life, storage behavior and plywood bonding. The development history therefore includes both mixed-resin chemistry and the practical demands of wood-panel manufacture.',patent('US2315087A','P. Cuvier, Preparation of phenol-urea-formaldehyde resins, US 2315087 A (1943).','Description, claims and 1940 priority.'),patent('US3547868A','F. Schwartzenburg Jr. and D. B. Griffin, Phenol-modified urea-formaldehyde resins and method of making same, US 3547868 A (1970), Reichhold Chemicals.','Description and adhesive evaluations for plywood, pot life and storage stability.'));
add(121,'Benzoguanamine–formaldehyde resin was an established amino-resin development platform by the 1950s. Richard Lindenfelser and Martha Kilthau’s American Cyanamid patent, filed in 1954 and issued in 1958, combined the resin with nitrile rubber to improve molding compositions. It documents a formulation advance aimed at overcoming limitations of the unmodified cured resin. Later coating work used benzoguanamine resins as crosslinking components, reflecting a shift between bulk molding and film-forming systems. The 1958 patent establishes a dated commercial research lineage; it does not establish the first synthesis of benzoguanamine or every benzoguanamine–formaldehyde resin.',patent('US2819246A','R. Lindenfelser and M. K. Kilthau, Molding compositions of benzoguanamine-formaldehyde reaction product and butadiene-acrylonitrile copolymer rubber, US 2819246 A (1958), American Cyanamid.','Description, resin/rubber molding compositions; 1954 filing.'),source('dupont-benzoguanamine-coating','dupont-corrosion-coating-patent','patent','DuPont, Corrosion inhibiting system containing zinc and zinc phosphate, US 3976617 A (1976).','https://patents.google.com/patent/US3976617A/en','Description, preferred benzoguanamine–formaldehyde aminoplast crosslinker in coatings.'));
const polyurethaneHistory = source('covestro-pu-80','covestro-polyurethane-history','manufacturer_technical_document','Covestro, 80 years of polyurethane, 10 November 2017.','https://www.covestro.com/press/80-years-of-polyurethane/','Chronology from 1937 chemistry through flexible foam, coatings, refrigerator insulation, sandwich panels and composites.');
add(122,'Thermoset polyurethanes grew from Otto Bayer and colleagues’ discovery of polyurethane chemistry in 1937. Commercial development required further work on isocyanates, polyols and formulation. Covestro’s historical chronology records flexible polyester-based foam in 1952, protective coatings in 1958, refrigerator insulation in 1962 and metal-faced building panels in 1970. Furniture, vehicle seating and thermal insulation became major outlets, while later developments included integral foams and reinforced composites. These dates describe important products in the Bayer/Covestro lineage; the broad thermoset category includes many networks and should not be assigned a single formulation or commercialization date.',polyurethaneHistory);
add(123,'Polyisocyanurate foams developed within the industrial chemistry of polyisocyanates as manufacturers sought cellular materials with useful thermal and fire behavior. By 1980, Upjohn’s patent literature described PIR foams as already widely used and cited a substantial earlier patent lineage. The 1980 development used esterified residues from dimethyl terephthalate manufacture as a formulation component and addressed the recurring tradeoff between brittleness and combustion behavior. It records an important stage in the engineering of rigid foams, rather than the invention of the isocyanurate group. The source does not establish one first-commercialization date for the entire PIR family.',patent('US4237238A','Polyisocyanurate foams based on esterified DMI oxidation residue additive, US 4237238 A (1980), Upjohn.','Background and summary, established PIR foams, friability and formulation development.'));
add(124,'The modern spray-polyurea industry is associated with rapid-reaction elastomer formulation and spray equipment, rather than the first observation of a urea-forming reaction. Dudley Primeaux II’s patent lineage, with priority in 1989 and a United States patent issued in 1996, documents aliphatic spray polyureas developed through Texaco Chemical and Huntsman. This work combined amine-containing components with isocyanates to make sprayed elastomeric materials. Primeaux’s later technical account describes the movement from laboratory development into commercial coating and lining applications. These milestones refer to spray elastomers; other polyurea architectures have separate histories.',patent('US5480955A','D. J. Primeaux II, Aliphatic spray polyurea elastomers, US 5480955 A (1996).','Description, spray elastomer systems and 1989 priority; Texaco/Huntsman assignment history.'),source('primeaux-spray-history','primeaux-polyurea-development','research_group_notes','D. J. Primeaux II, Polyurea Elastomer Technology: Bridging the Gap to Commercial Applications.','https://www.primeauxassociates.com/wp-content/uploads/2011/11/PP09.pdf','Development and application discussion of spray-polyurea elastomers.'));
add(125,'Alkyd resins became important coating binders during the interwar expansion of synthetic-resin chemistry. Roy Kienle and Lester Ferguson’s patent application of January 1927, issued in 1930, already used the term alkyd and addressed stable, pigmented coating compositions. It is a concrete early industrial milestone rather than a claim to every precursor polyester reaction. Oil-derived fatty components became central to alkyd paints and varnishes. Later development broadened feedstock choices and sought lower-solvent and more renewable coating systems; the 2023 review by C. Dizman and E. Cerrahoğlu Kaçakgil documents that continuation of an older coating platform.',patent('US1783364A','R. H. Kienle and L. V. Ferguson, Coating composition, US 1783364 A (1930), application filed 1927.','Description and claims, alkyd-resin neutralization and pigmented coatings.'),source('dizman-alkyd-history','dizman-bioalkyd-review','open_journal','C. Dizman and E. Cerrahoğlu Kaçakgil, Alkyd resins produced from bio-based resources for more sustainable and environmentally friendly coating applications, Turkish Journal of Chemistry 47 (2023), 1–23.','https://pmc.ncbi.nlm.nih.gov/articles/PMC10507036/','Introduction and renewable monomer/oil sections, coating uses and later feedstock developments.'));
const siliconeHistory = source('wuppertal-silicone-history','wuppertal-wacker-silicone-history','courseware','University of Wuppertal, A Historical Review of Silicones.','https://chemiedidaktik.uni-wuppertal.de/fileadmin/Chemie/chemiedidaktik/disido/en/info/structure/historical.htm','Kipping, Müller–Rochow synthesis and Wacker chronology for resins, rubbers and coatings.');
add(126,'Silicone resins emerged from early-twentieth-century organosilicon work by F. S. Kipping and the industrial precursor chemistry independently developed by Eugene Rochow and Richard Müller in 1940. A documented resin-production lineage is Wacker’s: its first silicone pilot plant and development of fluids and resins date to 1950. The company subsequently expanded into protective treatments and introduced combination resins for coatings in 1960. These are milestones for the resin branch of silicone technology; silicone rubber and silicone fluids followed related but distinct application paths.',siliconeHistory);
add(127,'Bismaleimide thermosets were developed during the 1960s search for heat-resistant addition-cured polymers. Friedrich Grundschober and Joerg Sambeth’s patent for Rhodiaceta, claiming Swiss priority in 1964 and issued in 1968, describes crosslinked materials made from bis-imides, including maleimides. The work demonstrates curing of low-molecular precursors into insoluble polymers and represents an early industrial foundation for BMI resin technology. Its importance was the combination of imide chemistry with an addition-curing route. The patent documents a particular research lineage; it does not establish the first synthesis of every bismaleimide monomer or the launch of every later composite grade.',patent('US3380964A','F. Grundschober and J. Sambeth, Reticulated polyimides and method of producing same from N,N′-bis-imides, US 3380964 A (1968), Rhodiaceta.','Description and maleimide examples; Swiss priority 1964.'));
add(128,'An important precursor to cyanate-ester resin technology was Grigat and Pütter’s 1963 preparation of cyanate esters from phenols, as summarized in the later manufacturing patent. Subsequent development converted these reactive precursors into thermoset systems. By 1990, Jack Boyd, Hermann Sitt, Hong-Son Ryang and Theodore Biermann’s BASF patent targeted radar-transparent structures using cyanate-containing matrices, adhesives and foams. That application illustrates why electrical behavior as well as temperature resistance shaped the family’s development. Later manufacturing work sought more controlled resin composition. These milestones distinguish monomer synthesis, formulated composite uses and production improvements.',patent('EP0863926B1','A process for the production of cyanate ester resins having unique composition, EP 0863926 B1 (2000).','Background citing Grigat and Pütter in 1963, resin composition and production objectives.'),patent('US4956393A','J. D. Boyd, H. Sitt, H.-S. Ryang and T. F. Biermann, Structures exhibiting improved transmission of ultrahigh frequency electromagnetic radiation and structural materials which allow their construction, US 4956393 A (1990).','Description and radome examples using cyanate matrices, adhesives and foams.'));
add(129,'Polybenzoxazines developed from benzoxazine monomer chemistry into a practical thermoset platform through work on synthesis and ring-opening cure. Hatsuo Ishida’s solventless synthesis patent, filed in 1994 and issued in 1996 through Edison Polymer Innovation, is an important documented milestone. It sought a practical route from phenols, amines and formaldehyde-containing reactants. Anthony Gallo’s later Henkel Loctite patent, filed in 1999 and issued in 2002, addressed preparation and cure of polybenzoxazine molding and coating compositions. This sequence records the movement toward usable resin systems; it should not be taken as the date of the earliest small-molecule benzoxazine synthesis.',patent('US5543516A','H. Ishida, Process for preparation of benzoxazine compounds in solventless systems, US 5543516 A (1996).','Background, solventless synthesis and 1994 filing.'),patent('US6376080B1','A. A. Gallo, Method for preparing polybenzoxazine, US 6376080 B1 (2002), Henkel Loctite.','Background and molding/coating composition development.'));
add(130,'Phthalonitrile thermoset development has a prominent United States Naval Research Laboratory lineage. A documented commercialization milestone came in May 2015, when NRL announced licenses for its second-generation PEEK-like phthalonitrile compositions. Teddy Keller, Matthew Laskoski and Andrew Saab were the inventors of the licensed technology. The intended uses included high-temperature, flame-resistant composites for military and civilian equipment. The announcement describes a later generation of an existing resin technology, not its first synthesis. It shows how government materials research moved toward commercial manufacture while addressing the practical combination of heat resistance, moisture behavior and composite processing.',source('nrl-phthalonitrile-license','nrl-phthalonitrile-development','institutional_reference','D. Parry, Naval Research Laboratory Licenses New Polymer Resin for Commercial Applications, United States Navy, 8 May 2015.','https://www.navy.mil/Press-Office/News-Stories/display-news/Article/2264749/naval-research-laboratory-licenses-new-polymer-resin-for-commercial-applications/','Full announcement, Keller/Laskoski/Saab inventorship, second-generation resin and licensing.'));
add(131,'Poly(furfuryl alcohol) resin was an established industrial research subject by the early 1950s. Quaker Oats’ patent filed in 1950 and issued in 1952 describes furfuryl-alcohol resin production, linking the material to the company’s industrial furan-chemicals business. The work concerns controlled resinification and useful resin products rather than discovery of the alcohol monomer. It illustrates the practical difficulty that shaped the field: controlling a readily polymerizing feedstock so that it could be manufactured and handled before final cure. The patent provides a dated production milestone, while the earliest resin observations and the full sequence of foundry-market introductions remain outside this account.',patent('US2601497A','Furfuryl alcohol resins, US 2601497 A (1952), Quaker Oats Company.','Description of controlled resin preparation and resin uses; 1950 application.'));
add(132,'Diallyl-phthalate thermosets developed through techniques for stopping polymerization at a useful prepolymer stage and completing cure after shaping. Charles Heiberger and James Thomas’s 1954 application, issued in 1958, describes solid prepolymers; subsequent FMC work produced a further preparation patent in 1968. These documents treat diallyl-phthalate polymerization as already known and focus on practical yield, isolation and handling. The resulting prepolymer route supported molding-resin technology rather than requiring the final article to be made directly from neat monomer. These are documented manufacturing advances, not a first-invention claim for the whole polymer.',patent('US2832758A','C. A. Heiberger and J. L. Thomas, Solid prepolymers of diallyl phthalate, US 2832758 A (1958).','Description of solid prepolymer production and molding use; 1954 application.'),patent('US3385836A','Preparation of diallyl phthalate prepolymers, US 3385836 A (1968), FMC.','Background and process improvements for isolable prepolymers.'));
add(133,'Thermosetting polyimides became important in high-temperature aerospace composites. NASA’s account traces polymerization-of-monomeric-reactants, or PMR, addition-polyimide technology to Lewis Research Center in the 1970s. PMR-15 became a widely used first-generation material for demanding composite components. Later NASA work by Kathy Chuang and Raymond Vannucci developed DMBZ-15, replacing the diamine used in PMR-15 while seeking improved high-temperature performance. This is the history of an influential thermosetting-polyimide lineage, not all polyimide chemistry. It shows the movement from laboratory resin design into aircraft-engine applications and subsequent reformulation of an established aerospace matrix.',source('nasa-pmr-history','nasa-pmr-polyimide-development','institutional_reference','NASA Spinoff, Polyimide Boosts High-Temperature Performance.','https://spinoff.nasa.gov/node/10560','Origins of PMR technology, PMR-15 applications and Chuang/Vannucci DMBZ-15 development.'));
const zeonHistory = source('zeon-chronology','zeon-company-history','manufacturer_technical_document','Zeon Corporation, History.','https://www.zeon.co.jp/en/company/history/','Dated chronology of rubber production, feedstock technology and overseas plants.');
const zeon75 = source('zeon-75-years','zeon-75-year-history','manufacturer_technical_document','Zeon Corporation, After 75 Years, Zeon Remains Strong as it Evolves with the Times.','https://www.zeon.co.jp/en/company/special/history/','Synthetic-rubber and C4/C5 technology development.');
const iisrpIR = source('iisrp-polyisoprene','iisrp-polyisoprene-history','institutional_reference','International Institute of Synthetic Rubber Producers, Polyisoprene.','https://iisrp.com/rubber/page/11','Historical background and applications; Shell 1960, Goodyear 1962, trans-polyisoprene producers.');
const arlanxeoBrands = source('arlanxeo-brands','arlanxeo-rubber-brands','manufacturer_technical_document','Arlanxeo, Our Brands.','https://www.arlanxeo.com/en/brands','Buna, Krynac, Baypren and Keltan product-family applications.');
add(134,'Natural rubber has no single inventor. Indigenous Mesoamerican communities processed plant latex into useful rubber by about 1600 BCE; archaeological and experimental work by Dorothy Hosler, Sandra Burkett and Michael Tarkanian documents balls, figurines and tool bindings. Industrial development was a much later history. Charles Goodyear’s sulfur-vulcanization discovery in 1839 helped make rubber goods usable across seasonal temperatures. Pneumatic tires then greatly expanded demand: Dunlop’s bicycle work and Michelin’s removable and automobile tires were influential late-nineteenth-century developments. Plantation research, improved latex harvesting and later block-rubber production changed the supply industry. Michelin’s radial-tire development further reinforced the importance of natural rubber alongside synthetic elastomers.',source('mit-ancient-rubber','mit-mesoamerican-rubber-research','institutional_reference','D. Halber, Rubber processed in ancient Mesoamerica, MIT researchers find, MIT News, 14 July 1999.','https://news.mit.edu/1999/rubber-0714','Hosler/Burkett/Tarkanian research, 1600 BCE processing and archaeological uses.'),source('ifc-rubber-history','ifc-natural-rubber-research-history','institutional_reference','Institut Français du Caoutchouc, History of research on rubber cultivation and natural rubber.','https://www.institutfrancaisducaoutchouc.org/en/history-of-research/','Vulcanization, pneumatic tires, radial tires, cultivation and granulation chronology.'));
add(135,'Synthetic cis-1,4-polyisoprene became practical when stereoselective catalysts of the 1950s allowed chemists to approach natural rubber’s chain configuration. Shell commercialized lithium-catalyzed isoprene rubber in 1960; Goodyear introduced its more highly cis-rich Natsyn material in 1962, followed by Goodrich-Gulf. Applications included tires, molded mechanical goods, footwear, rubber bands and nipples. Zeon began isoprene-rubber production in 1971 alongside its own isoprene-extraction technology, illustrating how monomer supply and polymer manufacture developed together. Later research continued to refine stereochemical control and processing; Goodyear’s 2004 neodymium-catalyst patent records one such manufacturing advance. Earlier rubberlike isoprene polymers should not automatically be identified as this highly cis-selective material.',iisrpIR,zeonHistory,patent('US6780948B2','Synthesis of polyisoprene with neodymium catalyst, US 6780948 B2 (2004), Goodyear.','Background and synthesis objectives for high-cis polyisoprene.'));
add(136,'Trans-1,4-polyisoprene has both a natural-material history and a later synthetic-polymer history. Gutta-percha was used in Southeast Asia for tool handles before its nineteenth-century introduction to European industry. William Montgomerie promoted medical uses in 1843; Werner Siemens’s cable-coating machinery helped make it central to submarine telegraph insulation. Golf balls and dental root fillings were other important uses of the natural material. Synthetic trans-polyisoprene was subsequently developed by producers including Polysar and Kuraray. Jack Lasky’s United States Rubber patent, issued in 1963, documents a stereoselective catalyst route. The nineteenth-century dates therefore concern natural gutta-percha and its processing, rather than invention of synthetic trans-polyisoprene.',source('nlb-gutta-history','nlb-gutta-percha-history','institutional_reference','T. Pwee, Tapping History, BiblioAsia, National Library Singapore (2007).','https://biblioasia.nlb.gov.sg/all-sections/vol-3-issue2-jul-2007-tapping-history/','Discovery, telegraphy and uses of natural gutta-percha.'),iisrpIR,patent('US3114744A','J. S. Lasky, Polymerization of isoprene to trans-1,4-polyisoprene, US 3114744 A (1963), United States Rubber.','Description of the vanadium/titanate/organoaluminum catalyst and trans product.'));
add(137,'Polybutadiene rubber’s industrial development includes successive generations of stereoselective catalyst technology. A documented Japanese production milestone is Zeon’s start of butadiene-rubber manufacture at Tokuyama in November 1965. Later, Thomas Knauf and Akhtar Osman’s Polysar patent, issued in 1995, sought a more active rare-earth catalyst system for producing high-cis polybutadiene. This illustrates continued refinement of a material already established commercially, rather than its original invention. Tire compounds have been a major outlet; Arlanxeo’s account also identifies plastic modification and golf balls as applications. The family encompasses different chain microstructures, so the launch of a particular high-cis grade is not a universal date for all polybutadiene.',zeonHistory,patent('US5428119A','T. F. Knauf and A. Osman, Process for polybutadiene production using catalyst with high activity, US 5428119 A (1995), Polysar.','Background and rare-earth catalyst improvements for high-cis rubber.'),arlanxeoBrands);
add(138,'The styrene–butadiene rubber family grew from German Buna-S research and became a strategic mass-production material during the Second World War. When access to Southeast Asian natural rubber was cut off, the United States government coordinated a GR-S program involving Firestone, B. F. Goodrich, Goodyear, Standard Oil of New Jersey, United States Rubber and academic laboratories. Commercial wartime plants began operating in 1942. The collaborative effort turned a laboratory and pilot-scale technology into a large industrial supply of general-purpose rubber for tires and other essential equipment. Postwar production and research continued, and later emulsion and solution processes developed into distinct branches with different product and manufacturing histories.',source('acs-synthetic-rubber','acs-us-synthetic-rubber-program','institutional_reference','American Chemical Society, U.S. Synthetic Rubber Program, National Historic Chemical Landmark (1998).','https://www.acs.org/education/whatischemistry/landmarks/syntheticrubber.html','Buna-S background and the government, industry and university GR-S production partnership.'));
add(139,'Emulsion SBR began with I. G. Farben’s Buna-S work in the 1930s. The United States wartime program began commercial production in 1942, initially using the hot-polymerization process. Development of cold-polymerized SBR in 1947 improved the practical rubber platform; government plants were subsequently sold or closed as the industry moved into private ownership. Tires remained an important driver of research. Howard Colvin and Michael Senyek’s 1999 Goodyear patent application sought emulsion-SBR tread formulations combining traction, rolling-resistance and wear objectives. These later formulation developments built on the original emulsion platform and should not be mistaken for its invention.',source('iisrp-esbr','iisrp-emulsion-sbr-history','institutional_reference','International Institute of Synthetic Rubber Producers, Emulsion Styrene-Butadiene Rubber.','https://iisrp.com/rubber','History section: Buna-S, 1942 production, 1947 cold rubber and postwar privatization.'),patent('EP0942042A2','H. A. Colvin and M. L. Senyek, Emulsion styrene-butadiene rubber, EP 0942042 A2 (1999), Goodyear.','Background and tire-tread formulation objectives.'));
add(140,'Solution SBR developed as a distinct way to control styrene–butadiene rubber architecture through organometallic polymerization. Ralph Farrar’s Phillips Petroleum patent, filed in 1977 and issued in 1979, documents coupling-agent addition during organolithium polymerization, including styrene–butadiene examples. It targeted processable rubbers for tires, hose, belting and related goods and treated solution polymerization as an established technology. Zeon began solution-SBR production at Tokuyama in 1986 and later opened production in Singapore in 2014. These milestones show continued process development and geographic expansion; they do not establish the first synthesis of the entire solution-SBR class.',patent('US4145498A','R. C. Farrar, Addition of coupling agent during organolithium initiated polymerizations, US 4145498 A (1979), Phillips Petroleum.','Background, styrene–butadiene examples and applications.'),zeonHistory);
add(141,'Carboxylated SBR belongs to the development of functional latex binders, where small amounts of acid functionality broadened the usefulness of styrene–butadiene copolymers. Paul Steinwand’s Union Oil patent, filed in 1989 and issued in 1991, describes carboxylated copolymer binders intended to improve wet strength in nonwoven fabrics. The application context included wipes, disposable medical products, carpet backings and durable textile goods. The patent’s subsequent assignment history runs through Rohm and Haas and Mallard Creek Polymers. This is a documented formulation and ownership lineage within an already developed latex field, rather than evidence that carboxylated SBR was first invented in 1991.',patent('US5039764A','P. J. Steinwand, Process for preparing carboxylated copolymers, US 5039764 A (1991), Union Oil Company of California.','Description of carboxylated styrene–butadiene binders, nonwoven applications and assignment history.'));
add(142,'Nitrile rubber emerged from the interwar search for useful synthetic elastomers. Erich Konrad and Eduard Tschunkur’s I. G. Farben patent, with 1930 German priority and a United States grant in 1934, describes rubberlike copolymers made from butadiene and polymerizable nitriles. It provides a firm early milestone for the family. Zeon began Japan’s first domestic nitrile-rubber production in 1959 and subsequently expanded its rubber and feedstock technology. Industrial development produced a range of specialty grades: Arlanxeo’s Krynac products, for example, serve adhesives, sealants and plastics modification. Later hydrogenated and carboxylated derivatives developed their own application histories rather than simply inheriting the original polymer’s invention date.',patent('US1973000A','E. Konrad and E. Tschunkur, Rubber like masses from butadiene hydrocarbons and polymerizable nitriles, US 1973000 A (1934), I. G. Farben.','1930 priority and butadiene–acrylonitrile examples.'),zeon75,arlanxeoBrands);
add(143,'Hydrogenated nitrile rubber developed as a heat- and oil-resistant extension of nitrile-rubber technology. A clear commercialization milestone is Zeon’s introduction of Zetpol in 1984. Its account identifies automotive timing belts as an important application, alongside other demanding mechanical rubber goods. The advance lay in producing a durable specialty elastomer from an existing nitrile-polymer platform; the much earlier invention of NBR is therefore not the invention date of HNBR. Zeon’s continued emphasis on controlled specialty-elastomer manufacture and automotive performance shows how hydrogenation created a commercially distinct branch of the nitrile family.',source('zeon-hnbr-launch','zeon-hnbr-commercial-history','manufacturer_technical_document','Zeon Chemicals, Making Rubber that Makes a Difference.','https://www.zeonchemicals.com/making-rubber-that-makes-a-difference/','Zetpol 1984 introduction and automotive timing-belt applications.'));
add(144,'Carboxylated nitrile rubber developed as a functional extension of the nitrile-latex platform. By 1999, Pascale Francine Jeanne Muller’s Goodyear patent application described it as widely used for gloves, nonwoven fabrics, masking tapes, seals and coating or binding applications. The proposed advance was emulsifier-free latex manufacture, aimed at reducing residual emulsifier in products and wash water. This is a useful dated stage in a longer development history: it demonstrates that XNBR was already established and that research had moved toward product cleanliness and manufacturing improvements. The document does not establish a first invention or launch date for all carboxylated nitrile rubbers.',patent('EP0955324A1','P. F. J. Muller, Emulsifier-free carboxylated nitrile rubber latex, EP 0955324 A1 (1999), Goodyear.','Background on established latex uses and emulsifier-free process objectives.'));
add(145,'William Sparks and Robert Thomas developed butyl rubber at Standard Oil of New Jersey in 1937 while investigating isobutylene-based materials. The Second World War created an urgent demand for synthetic rubber and drove the transition toward large-scale supply. Butyl’s air-retention behavior made it particularly useful in tire inner tubes, while subsequent uses included protective coatings, tapes and other industrial rubber goods. ExxonMobil’s company history preserves this Standard Oil research lineage. Later chlorination and bromination produced separate halobutyl branches for improved curing and tire construction; those modifications are later developments, rather than part of the original 1937 formulation.',source('invent-thomas-butyl','invent-sparks-thomas-butyl','institutional_reference','National Inventors Hall of Fame, Robert M. Thomas.','https://www.invent.org/inductees/robert-m-thomas','Sparks/Thomas research in 1937 and wartime synthetic-rubber production.'),source('exxon-butyl-history','exxon-company-history','manufacturer_technical_document','ExxonMobil, Our history.','https://corporate.exxonmobil.com/who-we-are/our-global-organization/our-history','1937 butyl-rubber milestone and subsequent uses.'),patent('US2964489A','F. P. Baldwin and R. M. Thomas, Process of chlorinating butyl rubber and vulcanizing the chlorinated product, US 2964489 A (1960).','Background and tire applications of the later halogenated derivative.'));
const butylReview = source('sone-butyl-history','sone-butyl-rubber-review','open_journal','T. Sone, Industrial Synthetic Method of the Rubbers: 5. Butyl Rubber, Nippon Gomu Kyokaishi 88 (2015), 473–478.','https://www.jstage.jst.go.jp/article/gomu/88/12/88_473/_pdf','Pages 473–474: commercial butyl in 1943, halobutyl development in the 1950s, Japan Butyl production.');
records.find(record => record.wopId === 'wop-000145').sources.push(butylReview);
add(146,'Bromobutyl belongs to the halogenated-butyl technologies developed during the 1950s to overcome ordinary butyl rubber’s slow curing. This is later chemistry than the parent butyl material’s 1930s origins. Eric George Kent and John Walker’s Polysar patent, with priority in 1972 and issued in 1976, documents continued work on peroxide-containing cure systems for bromobutyl. Tire air-retention applications became a principal outlet for halobutyl materials. A later industrial account by JSR researcher Takuo Sone identifies Japan Butyl, the JSR–ExxonMobil venture, as a producer of both brominated and chlorinated grades. These milestones trace development and manufacture without assigning a single first-commercialization date to every bromobutyl grade.',butylReview,patent('US3960988A','E. G. Kent and J. Walker, Vulcanization of bromobutyl, US 3960988 A (1976), Polysar.','1972 priority, background and free-radical cure-system development.'));
add(147,'Chlorobutyl emerged from the 1950s modification of butyl rubber to improve curing and compatibility in rubber assemblies. Francis Baldwin and Robert Thomas’s Standard Oil research lineage is documented in a patent issued in 1960. It describes controlled chlorination and applications in tubeless-tire inner linings, bonding layers and tire-curing bags. Those examples show why the modification mattered commercially: air retention had to be combined with workable cure and adhesion behavior. Later producers included Japan Butyl, the JSR–ExxonMobil venture. The 1960 patent is a dated technical milestone in chlorobutyl development, rather than a claim that all halobutyl materials were invented at that moment.',butylReview,patent('US2964489A','F. P. Baldwin and R. M. Thomas, Process of chlorinating butyl rubber and vulcanizing the chlorinated product, US 2964489 A (1960).','Description, tubeless-tire drawings, tie plies and curing-bag applications.'));
add(148,'Polychloroprene’s development is closely associated with DuPont’s Wallace Carothers laboratory. In April 1930 Arnold Collins isolated chloroprene and observed its polymerization; Elmer Bolton encouraged the company to develop the material commercially. The resulting Neoprene became an important early synthetic rubber, with an industrial introduction in 1931. Its history subsequently extended beyond that original DuPont lineage into multiple producers and specialty grades. Industrial applications included footwear, adhesives and technical rubber goods. The discovery therefore involved a team and subsequent process development, rather than Carothers alone.',source('shi-carothers-rubber','shi-carothers-biography','institutional_reference','Science History Institute, Wallace Hume Carothers.','https://www.sciencehistory.org/education/scientific-biographies/wallace-hume-carothers/','Collins’s April 1930 chloroprene work, Carothers and Bolton roles and commercialization.'),source('ifc-polychloroprene','ifc-natural-rubber-research-history','institutional_reference','Institut Français du Caoutchouc, History of research.','https://www.institutfrancaisducaoutchouc.org/en/history-of-research/','Synthetic elastomers section, DuPont neoprene in 1931.'),source('iisrp-polychloroprene-uses','iisrp-emulsion-sbr-history','institutional_reference','International Institute of Synthetic Rubber Producers, Synthetic Rubber Summary.','https://iisrp.com/rubber','Types and applications table, CR footwear, adhesives and technical goods.'));
const epmHistory = patent('US3300459A','G. Natta, G. Mazzanti and G. Boschi, Elastomeric copolymers of ethylene and propylene, US 3300459 A (1967), Montecatini Edison.','1955 Italian priority and amorphous ethylene–propylene copolymer description.');
const eneosEP = source('eneos-ep-uses','eneos-ethylene-propylene-rubber','manufacturer_technical_document','ENEOS Materials, Ethylene Propylene Rubber / EPM, EPDM.','https://www.eneos-materials.com/english/products/s_rubber/ep/','Applications and distinction between EPM and EPDM.');
add(149,'Ethylene–propylene rubber arose from the 1950s expansion of coordination-catalyst chemistry. Giulio Natta, Giorgio Mazzanti and Giorgio Boschi’s Montecatini patent lineage claims Italian priority in December 1955 for amorphous elastomeric ethylene–propylene copolymers. The Natta archive records a Ferrara plant milestone in 1958. These saturated copolymers provided an alternative rubber platform with subsequent uses in electrical insulation and industrial rubber products. Later addition of a diene produced the related EPDM branch, with different curing possibilities. The research dates, plant milestone and later applications describe distinct stages; they should not be collapsed into a single invention date for all ethylene–propylene elastomers.',epmHistory,source('natta-epr-history','natta-archive-patent-history','institutional_reference','Giulio Natta Archive, Part II: Patents.','https://www.giulionatta.it/ENG/parte_II.html','Discussion of ethylene–propylene rubbers and the Ferrara plant in 1958.'),eneosEP);
add(150,'EPDM developed from ethylene–propylene rubber by incorporating a diene to provide additional curing chemistry. The Society of Polymer Science, Japan’s chronology records DuPont and Montecatini production in 1963, followed by other manufacturers. DSM’s Keltan production at Geleen began in 1967; the later Arlanxeo site chronology documents additional lines in 1973 and 2003 and adoption of its ACE catalyst on the third line in 2013. Major application areas have included automotive seals and hoses, building membranes and electrical products. This sequence shows the progression from a new terpolymer platform to large-scale manufacture and later catalyst improvements, with supplier milestones distinguished from the earliest ethylene–propylene research.',source('spsj-epdm-history','spsj-polymer-chronology-1963','institutional_reference','Society of Polymer Science, Japan, Polymer history chronology, 1962–1963.','https://main.spsj.or.jp/nenpyo/1962-1963.htm','1963 industrial column, EPM/EPDM production by DuPont and Montecatini and later producers.'),source('arlanxeo-geleen-history','arlanxeo-keltan-geleen-history','manufacturer_technical_document','Arlanxeo, BRZO inspections presentation, 23 June 2022.','https://mvzo.org/wp-content/uploads/2022/06/3.-Arlanxeo-BRZO-inspecties-220623.pdf','Slide 3, Keltan Geleen production and catalyst chronology.'),eneosEP);
add(151,'Acrylic rubber was already the subject of dedicated United States government research during the 1940s. W. C. Mast and C. H. Fisher’s December 1948 report describes the Eastern Regional Research Laboratory’s Lactoprene elastomers, pilot-scale work and B. F. Goodrich’s commercial production. This establishes activity and manufacture by 1948 without claiming a unique first synthesis. Heat- and oil-resistant automotive seals, gaskets and hoses became important uses. Manabu Sugiyama’s 2016 Zeon account describes later demand from hotter engine compartments and identifies Zeon and Unimatec as major producers at that time. Across this history, incorporation of cure sites and development of reliable curing systems were recurring routes to useful acrylic elastomers.',source('usda-acrylic-1948','usda-mast-fisher-acrylic-history','public_report','W. C. Mast and C. H. Fisher, Improved preparation of acrylic rubber: Curing methods and properties of the vulcanizates, USDA AIC-206 (December 1948).','https://upload.wikimedia.org/wikipedia/commons/b/b9/Improved_preparation_of_acrylic_rubber_curing_methods_and_properties_of_the_vulcanizates_%28IA_improvedpreparat206mast%29.pdf','Title page and pages 1–2, laboratory work, Lactoprene EV, pilot production and Goodrich commercial manufacture.'),source('sugiyama-acrylic-history','sugiyama-acrylic-rubber-review','open_journal','M. Sugiyama, Industrial Synthetic Method of the Rubbers: 6. Acrylic Rubber, Nippon Gomu Kyokaishi 89 (2016), 10–15.','https://www.jstage.jst.go.jp/article/gomu/89/1/89_10/_pdf','Introduction, producers and cure-site development sections.'));
add(152,'Ethylene–acrylic elastomers became commercial materials when DuPont introduced Vamac in 1975. Their development sought to combine resistance to oils and oxidation with useful low-temperature flexibility. Anestis Logothetis’s DuPont patent, with a 1971 application lineage and issued in 1975, documents ethylene/alkyl-acrylate copolymers incorporating cure-site monomers. Automotive sealing became an important application, including cylinder-head-cover gaskets. Later grades and formulations developed both terpolymer and dipolymer branches with different cure systems. The early patent records a particular polymerization approach; it is evidence of the development effort, not proof that every commercial AEM grade uses that exact route.',patent('US3925326A','A. L. Logothetis, Alternating copolymers of ethylene/alkyl acrylates/cure-site monomers and a process for their preparation, US 3925326 A (1975), DuPont.','1971 priority, background and elastomer-development objectives.'),source('rado-aem-history','rado-aem-technical-guide','manufacturer_technical_document','RADO Gummi, Ethylene acrylic rubber (AEM).','https://www.rado-rubber.com/specialities/aem/','1975 Vamac introduction, gasket applications and later polymer/cure distinctions.'));
const epichlorohydrinHistory = source('shukla-pech-history','shukla-pech-history-review','open_journal','G. Shukla and R. C. Ferrier Jr., The versatile, functional polyether, polyepichlorohydrin: History, synthesis, and applications, Journal of Polymer Science 59 (2021), 2704–2718.','https://onlinelibrary.wiley.com/doi/full/10.1002/pol.20210514','Introduction and historical catalytic-development sections, Pruitt/Baggett, Vandenberg and Hydrin.');
const vandenbergOral = source('vandenberg-oral-history','shi-vandenberg-oral-history','institutional_reference','Edwin J. Vandenberg, oral history interview with Herman Skolnik, Science History Institute.','https://digital.sciencehistory.org/works/sb3979534','Transcript pages 44–47, catalyst discovery, licensing to Goodrich and subsequent Hercules production.');
add(153,'The useful rubber form of polyepichlorohydrin must be distinguished from earlier crystalline polymer. Pruitt and Baggett at Dow prepared semicrystalline material in 1954; Edwin Vandenberg at Hercules developed amorphous polyepichlorohydrin in 1957. In his oral history, Vandenberg describes discovering the importance of water-modified organoaluminum catalysts and the subsequent licensing arrangement with B. F. Goodrich. Hercules and Goodrich commercialized epichlorohydrin elastomers under Herclor and Hydrin names. The oil-resistant rubber platform supported hoses, seals and air ducts, while later research explored membranes and electrolytes. Those later applications include copolymers and modified materials, and should not all be assigned to the unmodified homopolymer.',epichlorohydrinHistory,vandenbergOral);
add(154,'Epichlorohydrin–ethylene oxide rubber emerged from Edwin Vandenberg’s Hercules research into high-molecular-weight polyethers. Adding ethylene oxide developed the amorphous epichlorohydrin platform into a distinct copolymer rubber. Vandenberg’s 1976 technical account identifies both Hercules and B. F. Goodrich as substantial producers, under the Herclor and Hydrin names, and explains the appeal of combining oil resistance with useful rubber and environmental behavior. The Hydrin business subsequently became associated with Zeon. Automotive fuel-system parts were an important outlet, and later grades also served conductive printer and copier components. These are milestones for the copolymer branch, rather than an independent discovery date inferred from the first epichlorohydrin homopolymer.',source('vandenberg-polyethers-1976','vandenberg-polyether-catalysts','open_journal','E. J. Vandenberg, A new class of polyethers—poly(1,4-dichloro-2,3-epoxybutane)s—synthesis, mechanism and property aspects, Pure and Applied Chemistry 48 (1976), 295–306.','https://publications.iupac.org/pac/pdf/1976/pdf/4803x0295.pdf','Pages 295–296, earlier epoxide catalyst work and commercial epichlorohydrin–ethylene oxide rubber.'),source('zeon-hydrin-history','zeon-hydrin-product-lineage','manufacturer_technical_document','Zeon Chemicals, Hydrin ECO Rubber Elastomers.','https://www.zeonchemicals.com/products/hydrin-eco/','Hydrin product family, fuel-system and electrostatic-dissipative applications.'),vandenbergOral);
add(155,'Chlorinated polyethylene developed as manufacturers learned to turn polyethylene into products ranging from flexible plastics to rubbers by controlling chlorination. Peter Canterino’s Phillips Petroleum patent, filed in 1955 and issued in 1963, records an early route and discusses tubing, electrical insulation and protective coatings. A later industrial milestone was Dow’s 1971 introduction of Tyrin made by aqueous-suspension chlorination. This helped develop an economical production platform with different residual-crystallinity grades. Wire and cable coverings and hose became major elastomer applications, while more crystalline or blended CPE served plastics modification. The histories overlap, but an impact-modifier grade should not automatically be treated as equivalent to crosslinked CPE rubber.',patent('US3110709A','P. J. Canterino, Chlorinated polyethylene, US 3110709 A (1963), Phillips Petroleum.','1955 filing; description of rubbery products, insulation, tubing and coatings.'),source('arp-cpe-history','arp-cpe-extrusion-history','manufacturer_technical_document','V. Kotian and N. Groves, CPE: A unique polymer for rubber and plastics extrusion, Rubber & Tire Digest (February–March 2022), 16–18, ARP Materials.','https://library.technobiz.org/uploadFiles/literature/00004/FebMarRTD2022_article%202.pdf','Page 16, Tyrin introduction in 1971, suspension process and major applications.'));
add(156,'Chlorosulfonated polyethylene developed through chemical modification of polyethylene into a curable specialty rubber. Heinz Noeske and Otto Roelen’s patent, issued in 1959, already describes conventional solution chlorosulfonation and proposes a solid-phase route for newer polyethylene feedstocks. It therefore records process development within an existing field. Tosoh began CSM production in November 1983 and later broadened the platform with its extos materials. Applications included industrial and automotive hoses, cable coverings, inflatable boats, linings and construction joints. The later supplier milestones concern production and application development, rather than the first synthesis of this established polymer family.',patent('US2889259A','H. Noeske and O. Roelen, Process for the chloro-sulfonation of polyethylene, US 2889259 A (1959).','Background on existing solution chlorosulfonation and solid-phase development.'),source('tosoh-csm-history','tosoh-company-history','manufacturer_technical_document','Tosoh Corporation, History of Challenges.','https://www.tosoh.co.jp/company/history/','November 1983, start of chlorosulfonated-polyethylene production.'),source('tosoh-csm-uses','tosoh-csm-product-family','manufacturer_technical_document','Tosoh Corporation, Chlorosulfonated Polyethylene (TOSO-CSM).','https://www.tosoh.co.jp/product/polymer/chlorosulfonated_polyethylene.html','CSM and extos development and application list.'));
add(157,'A major FKM milestone was DuPont’s development of Viton in 1957 from vinylidene fluoride and hexafluoropropylene. Its early aerospace sealing role expanded into automotive valve-stem and transmission seals, chemical equipment and other demanding gasket applications. The material subsequently diversified into grades with different fluorine contents and comonomers, balancing fluid resistance and low-temperature behavior. Daikin’s chronology records its own DAIEL fluoroelastomer launch in 1970, illustrating the growth beyond the original DuPont product lineage. The 1957 date belongs to Viton’s development; it should not be treated as the invention date of every fluorinated rubber or every later FKM composition.',source('cameo-viton-history','mfa-cameo-viton-history','institutional_reference','Museum of Fine Arts Boston, CAMEO, Viton.','https://cameo.mfa.org/wiki/Viton','Opening description: DuPont 1957, composition, grade diversification and industrial applications.'),daikin);
add(158,'Perfluoroelastomers became commercial sealing materials in the 1970s. The American Vacuum Society dates DuPont’s Kalrez perfluorocarbon elastomers to approximately 1975, consistent with DuPont’s fiftieth-anniversary announcement in 2025. O-rings and gaskets for aggressive chemical and thermal environments were central applications; electronics, oil and gas and chemical processing became major markets. Anestis Logothetis’s 1995 DuPont patent addressed the cost and speed of molding by developing combined cure chemistry for nitrile-containing perfluoroelastomers. The product line continued to grow, with a new Newark, Delaware manufacturing facility opened in 2023 to serve semiconductor and industrial demand. These are milestones in the Kalrez lineage and continuing FFKM development, not one invention date for all perfluoroelastomer formulations.',source('avs-kalrez-history','avs-vacuum-technology-timeline','institutional_reference','American Vacuum Society, Vacuum Science & Technology Timeline, 1972–2007.','https://avs.org/AVS/media/Files/History/timelineE.pdf','First page, Kalrez perfluorocarbon elastomers, DuPont, circa 1975.'),source('dupont-kalrez-anniversary','dupont-kalrez-fifty-years','manufacturer_technical_document','DuPont, DuPont Commemorates 50 Years of Innovation and Excellence with Kalrez Sealing Solutions, 15 April 2025.','https://www.prnewswire.com/news-releases/dupont-commemorates-50-years-of-innovation-and-excellence-with-kalrez-sealing-solutions-302426803.html','DuPont-issued announcement, anniversary and historical application sectors.'),patent('US5447993A','A. L. Logothetis, Perfluoroelastomer curing, US 5447993 A (1995), DuPont.','Technical Background and Field of the Invention, sealing applications and dual-cure development.'),source('dupont-kalrez-2023','dupont-kalrez-newark-expansion','manufacturer_technical_document','DuPont, DuPont Opens New Kalrez Production Site in Delaware, 6 November 2023.','https://www.dupont.com/news/dupont-opens-new-kalrez-production-site-in-delaware.html','Opening paragraphs, new manufacturing site and semiconductor/industrial demand.'));
add(159,'Tetrafluoroethylene–propylene rubber developed as a distinct alternative to vinylidene-fluoride-based fluoroelastomers. AGC dates development of its AFLAS material to 1971; Takashi Okazoe’s industrial history identifies commercialization by Asahi Glass in 1975. This distinction separates laboratory development from market introduction. The company developed applications in seals and cable coverings for chemical plants, oilfield equipment and transport. Later uses included railway and electric-vehicle cables, semiconductor facilities and space equipment, where combinations of heat, chemical and electrical demands mattered. AGC’s subsequent account emphasizes continued formulation development and work with users. These documented milestones apply to the TFE–propylene product lineage, while later AFLAS terpolymers require their own compositional scope.',fluorine,source('agc-aflas-history','agc-aflas-product-history','manufacturer_technical_document','AGC, AFLAS: fluororubber supporting innovation in automobiles and industrial equipment, 23 June 2022 (Japanese).','https://www.agc.com/hub/pr/AFLAS.html','1971 development paragraph; TFE/propylene structure and industrial, oilfield, railway, EV and space applications.'));
add(160,'Silicone rubber developed from the industrial siloxane chemistry enabled by the 1940 direct-process work of Eugene Rochow and Richard Müller. Wacker’s documented milestones include heat-vulcanizing rubber in 1953, room-temperature-vulcanizing rubber in 1955, building sealants in 1960 and addition-curing rubber in 1970. These are supplier milestones within a wider industry. Subsequent uses diversified into industrial rollers, electric-wire coverings and molded or extruded technical components, as illustrated by Shin-Etsu’s product families. In 1993, Toshio Takago and colleagues at Shin-Etsu patented a modified silicone platform aimed at improving strength while retaining transparency, documenting continuing development beyond the early filled rubber systems.',siliconeHistory,source('shinetsu-rubber-uses','shinetsu-rubber-performance-results','manufacturer_technical_document','Shin-Etsu, Silicone Rubber: Performance Test Results.','https://www.silicone.jp/e/catalog/pdf/rubber_et.pdf','Pages 3–5, general molding, extrusion, industrial roller and electrical-wire grades; application scope only.'),patent('US5247046A','T. Takago, S. Sato, N. Koike and T. Matsuda, RTV silicone rubber compositions and cured products, US 5247046 A (1993), Shin-Etsu.','Background and Summary, reinforcement/transparency problem and modified silicone development.'));
add(161,'Methyl-vinyl silicone rubber has a specific early patent milestone: James Marsden at General Electric filed in June 1945 and received a patent in 1948 for methyl silicone elastomers containing small amounts of silicon-bound vinyl groups. The work sought better hardness and recovery after compression. By 1956 Union Carbide was presenting a new vinyl-containing silicone rubber, and a subsequent patent records General Electric methyl-vinyl gums among commercially available materials in 1957. Norbert Dickmann’s 1957 Dow Corning patent developed a related blending approach to reduce compression set without the toxic additives used in some earlier formulations, with food and pharmaceutical uses explicitly motivating the work. These developments made curing and molded-part performance central to this silicone branch.',patent('US2445794A','J. Marsden, Methyl silicone elastomers containing Si-bonded vinyl radicals, US 2445794 A (1948), General Electric.','1945 filing; opening description and hardness/compression-set objectives.'),patent('US3107234A','Method of manufacture of silicone rubber, US 3107234 A (1963).','Opening historical discussion of Union Carbide’s 16 May 1956 presentation and General Electric gums listed in May 1957.'),patent('US2803619A','N. G. Dickmann, Low compression set siloxane elastomers containing a vinyl organosiloxane, US 2803619 A (1957), Dow Corning.','Opening description: earlier copolymer route, blending development and food/pharmaceutical motivation.'));
add(162,'Fluorosilicone rubber reached the market through Dow Corning’s Silastic LS-53 in 1957. A 1961 review by G. V. Odabashyan, V. A. Ponomarenko and A. D. Petrov describes its resistance to fuels, oils and hydraulic fluids and its use for aircraft gaskets. This application was an important reason to combine a siloxane backbone with fluorinated organic substituents. Development continued after that launch: John Razzano and Verne Simpson at General Electric patented a copolymerization method in 1976 that broadened the attainable fluorosilicone composition range. Their work aimed to tune resistance to hydrocarbon swelling more efficiently than blending separate silicone polymers. The commercial date therefore identifies an early product, while later copolymers represent further formulation and synthesis advances.',source('rcr-fluorosilicone-history','odabashyan-fluoro-organosilicon-review','open_journal','G. V. Odabashyan, V. A. Ponomarenko and A. D. Petrov, Organosilicon Compounds of Fluorine, Russian Chemical Reviews 30 (1961), 407–426.','https://www.russchemrev.org/RCR2993pdf','Page 418, Applications of fluoro-organosilicon compounds: Silastic LS-53 launch in 1957 and aircraft-gasket use.'),patent('US3974120A','J. S. Razzano and V. G. Simpson, Fluorosilicone copolymers and process for the preparation thereof, US 3974120 A (1976), General Electric.','Field of the Invention and background, expanded copolymer composition and comparison with blends.'));
add(163,'Commercial polysulfide rubber grew from Joseph Patrick and Nathan Mnookin’s interwar experiments. A 1958 account places their accidental rubber formation in 1926, during antifreeze research, followed by financing and formation of the Thiokol business. Solvent resistance distinguished the material, but early sales were limited. Liquid polysulfide developed in 1943 offered a more useful route to room-temperature-cured aircraft fuel-tank sealants. A further historical turn came at Caltech’s Jet Propulsion Laboratory: Charles Bartley filed his polysulfide-binder composite-propellant patent in 1946, issued in 1961. Thiokol then expanded into solid propulsion under Joseph Crosby. This history distinguishes the early solid rubber from later liquid, curable polysulfides that supported sealing and binder applications.',source('thiokol-contemporary-history','thompson-thiokol-1958-history','institutional_reference','E. T. Thompson, Solid Fuel Shift for Missiles Had Start in a “Shoestring” Here, Kansas City Star, 28 June 1958; reproduced in NASA JPL environmental-review materials, Attachment D.2.','https://jplwater.nasa.gov/docs/NAS710673.pdf','PDF page 176 (Attachment D.2), contemporary history of Patrick/Mnookin, Thiokol financing, 1943 liquid polymer, fuel-tank sealing and JPL collaboration.'),patent('US2997376A','C. E. Bartley, Solid composite propellant containing polysulfide rubber fuel binder, US 2997376 A (1961), California Institute Research Foundation.','1946 filing and opening description, historical binder application; no formulation or operating details reproduced.'));
add(164,'BASF traces its polyisobutylene development to Michael Otto’s 1931 work and a patent filed that year. Its 2026 history distinguishes this laboratory milestone from the industrial Oppanol plant that began production in 1938. The polymer’s subsequent uses ranged from cable insulation, roofing and pipeline coatings to insulating-glass sealants, adhesive bandages and chewing-gum formulations. Later research increasingly controlled molecular weight and reactive chain ends, enabling specialized additives and functional materials. A recent product milestone was BASF’s 2026 introduction of Oppanol N PLUS as a binder for emerging battery designs. These examples illustrate the breadth of the homopolymer platform; they do not make polyisobutylene identical to isoprene-containing butyl rubber.',source('basf-pib-history','basf-oppanol-ninety-five-years','manufacturer_technical_document','BASF, BASF introduces Oppanol N PLUS for next-generation batteries – 95 years of innovation with polyisobutene, 8 June 2026.','https://www.basf.com/global/en/media/news-releases/2026/06/p-26-096','Historical section: Michael Otto 1931, 1938 industrial plant, application list; opening section on battery binder.'),source('nifantev-pib-development','nifantev-polyisobutylene-review','open_journal','I. Nifant’ev and coauthors, Polyisobutylenes with Controlled Molecular Weight and Chain-End Structure: Synthesis and Actual Applications, Polymers (2023).','https://pmc.ncbi.nlm.nih.gov/articles/PMC10460079/','Introduction, controlled synthesis and application sections; later molecular-weight and chain-end development.'));
add(165,'Ethylene–octene elastomers became prominent within the 1990s commercialization of precisely controlled ethylene–alpha-olefin copolymers. A contemporary legal record documents Dow’s ENGAGE product line by February 1994, including two cable grades, followed by another wire-and-cable product that June. That is a dated milestone for the broader ENGAGE platform, not proof of the first synthesis of every ethylene–octene composition. Dow’s subsequent product guides distinguish ethylene–octene from ethylene–butene grades and describe their use in flexible and impact-modified thermoplastic olefins. Automotive bumpers, instrument panels and exterior trim became important outlets. Later development expanded melt-flow and melt-strength options to support injection molding, thermoforming and blow molding of application-specific compounds.',source('dow-engage-launch','dow-exxon-1998-court-history','institutional_reference','United States Court of Appeals for the Federal Circuit, Dow Chemical Company v. Exxon Corporation, 24 March 1998, Background (FindLaw reproduction).','https://caselaw.findlaw.com/court/us-federal-circuit/1097572.html','Background paragraphs 1–2, AFFINITY and ENGAGE introductions and 1994 cable-grade dates; commercial chronology only.'),source('dow-engage-octene','dow-engage-transportation-selection','manufacturer_technical_document','Dow, ENGAGE Polyolefin Elastomers: Product selection guide for transportation applications, Form 777-088-01E-0626 (2026).','https://www.dow.com/documents/777/777-088-01-engage-polyolefin-elastomer-product-selection-guide.pdf?iframe=true','Pages 1–3, explicit ethylene–octene grade family, automotive applications and subsequent processing-grade development.'));
export default records;
